  1→import {
  2→  useCallback,
  3→  useEffect,
  4→  useRef,
  5→  useState,
  6→  type ReactNode,
  7→} from 'react';
  8→import { AgentContext } from '../hooks/useAgent';
  9→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
 10→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 11→import { useSessionId } from '../hooks/useSessionId';
 12→import { generateUUID } from '../utils/uuid';
 13→
 14→function generateId() {
 15→  return generateUUID();
 16→}
 17→
 18→export function AgentProvider({
 19→  children,
 20→  refreshTables,
 21→}: {
 22→  children: ReactNode;
 23→  refreshTables: () => Promise<void>;
 24→}) {
 25→  const userSessionId = useSessionId();
 26→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 27→  const [isStreaming, setIsStreaming] = useState(false);
 28→  const abortRef = useRef<AbortController | null>(null);
 29→  const textBufferRef = useRef('');
 30→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 31→  const assistantIdRef = useRef('');
 32→  const segmentsRef = useRef<ContentSegment[]>([]);
 33→  const currentTextRef = useRef('');
 34→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 35→  const sessionIdRef = useRef<string | null>(null);
 36→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 37→  // Keep a ref in sync with messages so sendMessage always reads the latest
 38→  const messagesRef = useRef<ChatMessage[]>(messages);
 39→  useEffect(() => { messagesRef.current = messages; }, [messages]);
 40→  // Cache messages per conversation so switching away doesn't lose in-progress data
 41→  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
 42→  // Track which conversation is currently displayed so background streams can detect they're stale
 43→  const activeConversationIdRef = useRef<string | null>(null);
 44→
 45→  const flushText = useCallback(() => {
 46→    const text = textBufferRef.current;
 47→    if (!text) return;
 48→    const id = assistantIdRef.current;
 49→    currentTextRef.current += text;
 50→    setMessages((prev) =>
 51→      prev.map((m) =>
 52→        m.id === id ? { ...m, content: m.content + text } : m
 53→      )
 54→    );
 55→    textBufferRef.current = '';
 56→  }, []);
 57→
 58→  const sendMessage = useCallback(
 59→    async (text: string, conversationId?: string | null) => {
 60→      if (isStreaming) return;
 61→
 62→      const userMsg: ChatMessage = {
 63→        id: generateId(),
 64→        role: 'user',
 65→        content: text,
 66→      };
 67→
 68→      const assistantId = generateId();
 69→      assistantIdRef.current = assistantId;
 70→      const assistantMsg: ChatMessage = {
 71→        id: assistantId,
 72→        role: 'assistant',
 73→        content: '',
 74→        toolCalls: [],
 75→        isStreaming: true,
 76→      };
 77→
 78→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 79→      setIsStreaming(true);
 80→      textBufferRef.current = '';
 81→      segmentsRef.current = [];
 82→      currentTextRef.current = '';
 83→      phaseRef.current = 'thinking';
 84→
 85→      // Build conversation history from current messages for resume fallback.
 86→      // Read from messagesRef (not the stale closure `messages`) so that
 87→      // switching conversations is reflected immediately.
 88→      const history = messagesRef.current
 89→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 90→        .map((m) => ({ role: m.role, content: m.content }));
 91→
 92→      // If there's pending history from a delete, start a new Langfuse session with that context
 93→      const pendingHistory = pendingHistoryRef.current;
 94→      pendingHistoryRef.current = null;
 95→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
 96→
 97→      const controller = new AbortController();
 98→      abortRef.current = controller;
 99→
100→      // Extract all /skill-name references from message
101→      let actualMessage = text;
102→      let skills: string[] | undefined;
103→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
104→      if (slashMatches.length > 0) {
105→        skills = slashMatches.map((m) => m[1]);
106→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
107→      }
108→
109→      await runAgentLoop(
110→        actualMessage,
111→        sessionIdRef.current,
112→        langfuseSessionId,
113→        pendingHistory ?? (history.length > 0 ? history : null),
114→        conversationId,
115→        {
116→          onTextChunk: (chunk) => {
117→            textBufferRef.current += chunk;
118→            if (!flushTimerRef.current) {
119→              flushTimerRef.current = setTimeout(() => {
120→                flushText();
121→                flushTimerRef.current = null;
122→              }, 50);
123→            }
124→          },
125→          onThinkingDone: () => {
126→            // Extended thinking just ended and a text block is starting.
127→            // Create a thinking segment from accumulated thinking text.
128→            if (flushTimerRef.current) {
129→              clearTimeout(flushTimerRef.current);
130→              flushTimerRef.current = null;
131→            }
132→            flushText();
133→            if (currentTextRef.current.trim()) {
134→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
135→              currentTextRef.current = '';
136→            }
137→            phaseRef.current = 'answer';
138→            setMessages((prev) =>
139→              prev.map((m) =>
140→                m.id === assistantId
141→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
142→                  : m
143→              )
144→            );
145→          },
146→          onToolCall: (pending: ToolCallResult) => {
147→            if (flushTimerRef.current) {
148→              clearTimeout(flushTimerRef.current);
149→              flushTimerRef.current = null;
150→            }
151→            flushText();
152→            if (currentTextRef.current.trim()) {
153→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
154→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
155→              currentTextRef.current = '';
156→            }
157→            // Add a pending tool segment so the input is shown immediately
158→            segmentsRef.current.push({
159→              type: 'tool',
160→              toolResult: pending,
161→            });
162→            setMessages((prev) =>
163→              prev.map((m) =>
164→                m.id === assistantId
165→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
166→                  : m
167→              )
168→            );
169→          },
