626→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
627→    activeConversationIdRef.current = incomingConversationId || null;
628→
629→    // Don't abort the SSE stream — let the backend agent continue running
630→    // in the background.  The onDone/onError callbacks detect that the
631→    // conversation has changed and handle cleanup (cache invalidation).
632→    // Only clear the flush timer so it doesn't interfere with the new
633→    // conversation's state.
634→    if (flushTimerRef.current) {
635→      clearTimeout(flushTimerRef.current);
636→      flushTimerRef.current = null;
637→    }
638→
639→    // Prefer cached messages when the cache is at least as complete as
640→    // the backend response (cache keeps rich segments / streaming data).
641→    let finalMsgs = msgs;
642→    if (incomingConversationId) {
643→      const cached = messagesCacheRef.current.get(incomingConversationId);
644→      if (cached && cached.length > 0 && cached.length >= msgs.length) {
645→        finalMsgs = cached;
646→      }
647→      // Clear used cache entry so stale data doesn't persist forever
648→      messagesCacheRef.current.delete(incomingConversationId);
649→    }
650→
651→    // Capture ref values NOW — React 18 batching may defer the updater
652→    // function below until after the ref resets at the bottom of this
653→    // function, so reading refs inside the updater would see empty values.
654→    const capturedTextBuffer = textBufferRef.current;
655→    const capturedAssistantId = assistantIdRef.current;
656→    const capturedSegments = [...segmentsRef.current];
657→    const capturedCurrentText = currentTextRef.current;
658→    const capturedPhase = phaseRef.current;
659→
660→    // Save current messages to cache before replacing them.
661→    setMessages(prev => {
662→      if (outgoingConversationId && prev.length > 0) {
663→        const pendingText = capturedTextBuffer;
664→        const aId = capturedAssistantId;
665→
666→        // Build finalized segments including any unflushed text
667→        let finalSegments = [...capturedSegments];
668→        const pendingSegmentText = capturedCurrentText + pendingText;
669→        if (pendingSegmentText.trim()) {
670→          const segType = capturedPhase === 'answer' ? 'answer' : 'thinking';
671→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
672→        }
673→
674→        const cleaned = prev.map(m => {
675→          if (m.id === aId && m.isStreaming) {
676→            return {
677→              ...m,
678→              content: m.content + pendingText,
679→              isStreaming: false,
680→              currentPhase: undefined,
681→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
682→            };
683→          }
684→          return m;
685→        });
686→        const toCache = cleaned.filter(m => {
687→          if (m.role === 'assistant' && !m.content?.trim() && (!m.segments || m.segments.length === 0)) {
688→            return false;
689→          }
690→          return true;
691→        });
692→        messagesCacheRef.current.set(outgoingConversationId, toCache);
693→      }
694→      return finalMsgs;
695→    });
696→
697→    setIsStreaming(false);
698→    textBufferRef.current = '';
699→    currentTextRef.current = '';
700→    segmentsRef.current = [];
701→    assistantIdRef.current = '';
702→    phaseRef.current = 'thinking';
703→    sessionIdRef.current = null;
704→    pendingHistoryRef.current = null;
705→  }, []);
706→
707→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
708→    activeConversationIdRef.current = null;
709→    if (abortRef.current) {
710→      abortRef.current.abort();
711→      abortRef.current = null;
712→    }
713→    if (flushTimerRef.current) {
714→      clearTimeout(flushTimerRef.current);
715→      flushTimerRef.current = null;
716→    }
717→
718→    // Capture refs before setMessages (React 18 batching may defer the updater)
719→    const capturedTextBuffer = textBufferRef.current;
720→    const capturedAssistantId = assistantIdRef.current;
721→    const capturedSegments = [...segmentsRef.current];
722→    const capturedCurrentText = currentTextRef.current;
723→    const capturedPhase = phaseRef.current;
724→
725→    setMessages(prev => {
726→      if (outgoingConversationId && prev.length > 0) {
727→        const pendingText = capturedTextBuffer;
728→        const aId = capturedAssistantId;
729→        let finalSegments = [...capturedSegments];
730→        const pendingSegmentText = capturedCurrentText + pendingText;
731→        if (pendingSegmentText.trim()) {
732→          const segType = capturedPhase === 'answer' ? 'answer' : 'thinking';
733→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
734→        }
735→        const cleaned = prev.map(m => {
736→          if (m.id === aId && m.isStreaming) {
737→            return {
738→              ...m,
739→              content: m.content + pendingText,
740→              isStreaming: false,
741→              currentPhase: undefined,
742→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
743→            };
744→          }
745→          return m.isStreaming ? { ...m, isStreaming: false, currentPhase: undefined } : m;
746→        });
747→        const toCache = cleaned.filter(m => {
748→          if (m.role === 'assistant' && !m.content?.trim() && (!m.segments || m.segments.length === 0)) {
749→            return false;
750→          }
751→          return true;
752→        });
753→        messagesCacheRef.current.set(outgoingConversationId, toCache);
754→      }
755→      return [];
756→    });
757→    setIsStreaming(false);
758→    textBufferRef.current = '';
759→    currentTextRef.current = '';
760→    segmentsRef.current = [];
761→    assistantIdRef.current = '';
762→    phaseRef.current = 'thinking';
763→    sessionIdRef.current = null;
764→    pendingHistoryRef.current = null;
765→  }, []);
766→
767→  return (
768→    <AgentContext.Provider
769→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion }}
770→    >
771→      {children}
772→    </AgentContext.Provider>
773→  );
